public Collection<Vet> findVets() throws DataAccessException {
    return vetRepository.findAll();
}

/**
 * The number of owners, counted from the very first one ever created, that receive the
 * {@code FOUNDING} membership tier. Every owner created after this threshold is {@code STANDARD}.
 */
private static final int MAX_FOUNDING_OWNERS = 100;

@Override
@Transactional
public void saveOwner(Owner owner) throws DataAccessException {
    if (owner.isNew()) {
        if (owner.getRegistrationDate() == null) {
            owner.setRegistrationDate(LocalDate.now());
        }
        if (isDailyRegistrationLimitReached(owner)) {
            throw new OwnerRegistrationLimitException(
                "The maximum number of owners that can be registered today has been reached");
        }
        if (isCityCapacityReached(owner)) {
            throw new OwnerCityCapacityException(
                "The maximum number of owners that can be registered in this city has been reached");
        }
        owner.setCity(resolveCity(owner));
        owner.setMembershipNumber(ownerRepository.findAll().size() + 1);
        owner.setMembershipTier(owner.getMembershipNumber() <= MAX_FOUNDING_OWNERS ? "FOUNDING" : "STANDARD");
        owner.setCustomerCode(generateCustomerCode(owner));
        owner.setNamesakeCount(countNamesakes(owner));
        owner.setSharesHousehold(sharesHousehold(owner));
        owner.setLocality(resolveLocality(owner));
        if (isDuplicateTelephone(owner)) {
            throw new DuplicateOwnerException(
                "An owner with the same telephone already exists");
        }
        if (isDuplicateEmail(owner)) {
            throw new DuplicateOwnerException(
                "An owner with the same email already exists");
        }
    }
    ownerRepository.save(owner);

}

/**
 * Count how many other owners already share this owner's last name at the
 * moment of creation (compared case-insensitively). The owner being created
 * is not yet persisted and is therefore never included in the count.
 */
private int countNamesakes(Owner owner) {
    String lastName = owner.getLastName();
    if (lastName == null) {
        return 0;
    }
    return (int) ownerRepository.findAll().stream()
        .filter(existing -> !existing.getId().equals(owner.getId()))
        .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
        .count();
}

/**
 * Determine whether a newly created owner shares a household with an
 * existing owner, i.e. another owner already has the same address and city
 * (both compared case-insensitively) at the moment of creation. The owner
 * being created is not yet persisted and is therefore never matched against
 * itself.
 */
private boolean sharesHousehold(Owner owner) {
    String address = owner.getAddress();
    String city = owner.getCity();
    if (address == null || city == null) {
        return false;
    }
    return ownerRepository.findAll().stream()
        .filter(existing -> !existing.getId().equals(owner.getId()))
        .anyMatch(existing -> address.equalsIgnoreCase(existing.getAddress())
            && city.equalsIgnoreCase(existing.getCity()));
}

/**
 * Determine a newly created owner's locality at the moment of creation.
 * Returns {@code "local"} when the owner's city is the single most common
 * city among the existing owners (compared case-insensitively); that is,
 * exactly one city occurs more often than every other and it is this
 * owner's city. In every other case (no existing owners, a tie for the most
 * common city, or a different city being the most common) the owner is
 * {@code "remote"}. The owner being created is not yet persisted and is
 * therefore never counted.
 */
private String resolveLocality(Owner owner) {
    String city = owner.getCity();
    if (city == null) {
        return "remote";
    }
    Map<String, Long> countsByCity = ownerRepository.findAll().stream()
        .filter(existing -> !existing.getId().equals(owner.getId()))
        .filter(existing -> existing.getCity() != null)
        .collect(Collectors.groupingBy(
            existing -> existing.getCity().toLowerCase(Locale.ROOT),
            Collectors.counting()));
    if (countsByCity.isEmpty()) {
        return "remote";
    }
    long max = countsByCity.values().stream().mapToLong(Long::longValue).max().orElse(0L);
    long citiesAtMax = countsByCity.values().stream().filter(count -> count == max).count();
    if (citiesAtMax != 1) {
        return "remote";
    }
    long ownerCityCount = countsByCity.getOrDefault(city.toLowerCase(Locale.ROOT), 0L);
    return ownerCityCount == max ? "local" : "remote";
}

