     * Determine whether the daily registration limit has already been reached for the day the given
     * owner is being registered on. Counts the existing owners whose registration date matches the new
     * owner's registration date and returns {@code true} once that count has reached
     * {@link #MAX_OWNERS_PER_DAY}.
     */
    private boolean isDailyRegistrationLimitReached(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        if (registrationDate == null) {
            return false;
        }
        long registeredToday = ownerRepository.findAll().stream()
            .filter(existing -> !existing.getId().equals(owner.getId()))
            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
            .count();
        return registeredToday >= MAX_OWNERS_PER_DAY;
    }

    /**
     * The maximum number of owners that may be registered in any single city (compared case-insensitively).
     */
    private static final int MAX_OWNERS_PER_CITY = 8;

    /**
     * Determine whether the given owner's city has already reached its capacity. Counts the existing owners
     * whose city matches the new owner's city (compared case-insensitively) and returns {@code true} once
     * that count has reached {@link #MAX_OWNERS_PER_CITY}. An owner without a city is never at capacity.
     */
    private boolean isCityCapacityReached(Owner owner) {
        String city = owner.getCity();
        if (city == null) {
            return false;
        }
        long ownersInCity = ownerRepository.findAll().stream()
            .filter(existing -> !existing.getId().equals(owner.getId()))
            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
            .count();
        return ownersInCity >= MAX_OWNERS_PER_CITY;
    }

    private boolean isDuplicateTelephone(Owner owner) {
        String telephone = normalizeTelephone(owner.getTelephone());
        return ownerRepository.findAll().stream()
            .anyMatch(existing -> !existing.getId().equals(owner.getId())
                && Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
    }

    /**
     * Normalize a telephone number for duplicate detection by stripping every
     * character that is not a digit (spaces, dashes and parentheses), so that
     * "(613) 555-0100" and "6135550100" are treated as the same number. A
     * {@code null} value stays {@code null}.
     */
    private static String normalizeTelephone(String value) {
        if (value == null) {
            return null;
        }
        return value.replaceAll("[^0-9]", "");
    }

    private boolean isDuplicateEmail(Owner owner) {
        String email = owner.getEmail();
        if (email == null || email.isBlank()) {
